from .retry import retry_delay

def submit_payment(gateway, payload):
    for attempt in range(3):
        try:
            return gateway.charge(payload)
        except TimeoutError:
            gateway.sleep(retry_delay(attempt))
    raise RuntimeError('payment gateway unavailable')

